\title{The Type/Coset Channel of a Finite Group:\\ The Transitive Quintic Row in Closed Form}
\author{Aristotle}
\date{17 September 2026}

\begin{document}
\maketitle

\begin{abstract}
Attached to a degree-$n$ irreducible polynomial $f\in\mathbb{Q}[x]$ with Galois group $G\le S_n$ and an unramified prime $p$ are two observables: the \emph{factorization type} $T$ of $f\bmod p$ (equivalently, the cycle type of the Frobenius class of $p$) and the \emph{abelianization coset} $C$, the image of that class in $A=G/[G,G]$, which class field theory realizes as a function of $p$ modulo a conductor $m^\ast$. By the Chebotarev density theorem the joint law of $(T,C)$ over primes is the joint law of those two functions at a uniformly random element of $G$; we study this finite object as an information channel. We prove the \emph{Abelianization Law}: if every type occurs with a single coset then $I(T;C)=H(C)=\log_2|A|$, which together with the gap identity $H(T)-I(T;C)=H(T\mid C)$ pins every Shannon quantity of the channel. We prove its \emph{converse}: for an arbitrary finite table $I(T;C)=H(C)$ if and only if the type determines the coset, so a single ambiguous type strictly lowers the transmitted information. We prove a \emph{residue-dial invariance}: refining the coset alphabet along any $m$-to-one map, spreading mass uniformly, adds exactly $\log_2 m$ bits to both the coset and the joint entropy and leaves $I$ unchanged. We prove a \emph{pair law} and its arity-$k$ generalization together with a \emph{which-factor wall}. Applying these to the five transitive subgroups of $S_5$ closes the quintic row in exact closed form: $I(T;C)=\log_2 5-\tfrac85,\,1,\,\tfrac32,\,0,\,1$ for $C_5, D_5, F_{20}, A_5, S_5$. The $D_5$ cell is realized inside the dihedral group of order ten, whose commutator subgroup is identified with the rotation subgroup by exhibiting each rotation as a single commutator; its quadratic character is \emph{not} the discriminant character, and for $x^5+20x+32$ it is that of the quadratic resolvent $\mathbb{Q}(\sqrt{-5})$ of conductor $20$. Finally $F_{20}$ is the unique non-saturating cell: its type $[4]$ straddles both generators of $C_4$, forcing $I=3/2<2=H(C)$.
\end{abstract}

\section{Introduction}

\subsection{Two observables at a prime}

Let $f\in\mathbb{Z}[x]$ be monic, irreducible of degree $n$, with splitting field $L/\mathbb{Q}$ and Galois group $G=\Gal(L/\mathbb{Q})$, regarded as a transitive subgroup of $S_n$ through its action on the roots. For each prime $p\nmid\disc(f)$ the Frobenius conjugacy class $\Frob_p\subseteq G$ is defined and Dedekind's theorem gives
\[
\text{cycle type of }\Frob_p \;=\; \text{multiset of degrees of the irreducible factors of } f \bmod p .
\]
Write $T(p)$ for this common value, the \emph{factorization type}: a class function computable by polynomial factorization over $\mathbb{F}_p$.

Let $A=G^{\ab}=G/[G,G]$ and $\varphi:G\twoheadrightarrow A$. As $A$ is abelian, $\varphi$ is constant on conjugacy classes, so $C(p):=\varphi(\Frob_p)$ is well defined: the \emph{abelianization coset}. The fixed field of $[G,G]$ is the maximal abelian subextension; by class field theory it lies in $\mathbb{Q}(\zeta_{m^\ast})$ and the Artin map exhibits $C(p)$ as a function of $p\bmod m^\ast$ through a surjection $(\mathbb{Z}/m^\ast)^\times\twoheadrightarrow A$. In words: \emph{the abelianization coset is exactly the part of the Frobenius data that a congruence condition on $p$ can detect.}

\subsection{The channel point of view}

Chebotarev's theorem says the Frobenius classes equidistribute, so the joint density of $(T(p),C(p))$ over primes equals the joint law of $(T(g),\varphi(g))$ for $g$ uniform in $G$. This is a finite table with Shannon entropies, and it poses a well-defined question: \emph{how many bits does the factorization shape of $f\bmod p$ reveal about the residue class of $p$?} The answer is the mutual information $I(T;C)$; the content of this paper is that it is computable exactly, is governed by a structural law with a sharp converse, and is verified without exception across all of degree five.

\section{The type/coset channel}

\begin{definition}[Joint table]
Let $\iota$ (types) and $\kappa$ (cosets) be finite nonempty sets. A \emph{joint table} is $p:\iota\times\kappa\to\mathbb{R}_{\ge0}$ with $\sum_{t,c}p(t,c)=1$. Its marginals are $p_T(t)=\sum_c p(t,c)$ and $p_C(c)=\sum_t p(t,c)$.
\end{definition}

\begin{definition}[Entropies]
With $\eta(x)=-x\log x$ and $\eta(0)=0$, in bits,
\[
H(T)=\tfrac{1}{\log 2}\sum_t\eta(p_T(t)),\quad H(C)=\tfrac{1}{\log 2}\sum_c\eta(p_C(c)),\quad H(T,C)=\tfrac{1}{\log 2}\sum_{t,c}\eta(p(t,c)),
\]
\[
I(T;C)=H(T)+H(C)-H(T,C),\quad H(T\mid C)=H(T,C)-H(C),\quad H(C\mid T)=H(T,C)-H(T).
\]
\end{definition}

\begin{definition}[Group table]
For a finite nonempty group $G$ and observables $T:G\to\iota$, $C:G\to\kappa$, the \emph{group table} has cells
$p(t,c)=\#\{g\in G: T(g)=t,\ C(g)=c\}/|G|$.
\end{definition}

\begin{theorem}[Gap identity]\label{thm:gap}
For any joint table, $H(T)-I(T;C)=H(T\mid C)$.
\end{theorem}
\begin{proof}
$H(T)-\bigl(H(T)+H(C)-H(T,C)\bigr)=H(T,C)-H(C)$.
\end{proof}

Algebraically trivial, this identity is the interpretive backbone: whatever the transmitted information turns out to be, the entire residual type entropy is accounted for as coset-conditioned entropy.

\begin{lemma}[Pointwise domination]\label{lem:dom}
If $0\le a\le b$ then $a(-\log b)\le\eta(a)$.
\end{lemma}
\begin{proof}
For $a=0$ both sides vanish; for $0<a\le b$, $\log a\le\log b$ gives $a\log a\le a\log b$, i.e.\ $-a\log b\le\eta(a)$.
\end{proof}

\begin{theorem}[Nonnegative conditional entropies]\label{thm:condnn}
$H(T\mid C)\ge 0$ and $H(C\mid T)\ge 0$.
\end{theorem}
\begin{proof}
Expand $\sum_c\eta(p_C(c))=\sum_{c}\sum_t p(t,c)(-\log p_C(c))$ and apply Lemma~\ref{lem:dom} cellwise with $a=p(t,c)\le b=p_C(c)$; summing gives $H(C)\le H(T,C)$. The other statement follows by transposing the table, which preserves $H(T,C)$.
\end{proof}

\begin{theorem}[Nonnegative information]\label{thm:Inn}
$I(T;C)\ge0$, hence $0\le I(T;C)\le\min\{H(T),H(C)\}$.
\end{theorem}
\begin{proof}
On the support $S=\{(t,c):p(t,c)>0\}$,
$I(T;C)\log 2=-\sum_S p\log\frac{p_Tp_C}{p}$.
By $\log x\le x-1$, $\sum_S p\log\frac{p_Tp_C}{p}\le\sum_S(p_Tp_C-p)\le 1-1=0$, using $\sum_S p=1$ and $\sum_S p_Tp_C\le\sum_{t,c}p_T(t)p_C(c)=1$. The upper bounds are Theorem~\ref{thm:condnn} with Theorem~\ref{thm:gap}.
\end{proof}

\section{The Abelianization Law}

\begin{definition}[Determination]
The type \emph{determines} the coset if $p(t,c)>0$ and $p(t,c')>0$ imply $c=c'$; equivalently each row is supported on a single cell.
\end{definition}

\begin{lemma}[Single-cell rows]\label{lem:single}
If a nonnegative finite family has at most one positive member then $\sum_a\eta(f_a)=\eta\bigl(\sum_a f_a\bigr)$.
\end{lemma}

\begin{theorem}[Abelianization Law, abstract form]\label{thm:ablaw}
If the type determines the coset then $I(T;C)=H(C)$, and consequently $H(T)-I(T;C)=H(T)-H(C)=H(T\mid C)$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:single} applied to each row, $H(T,C)=H(T)$; hence $I=H(T)+H(C)-H(T)=H(C)$.
\end{proof}

\begin{theorem}[Dual law]\label{thm:dual}
If the coset determines the type, then $I(T;C)=H(T)$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:ablaw} to the transposed table; $I$ and $H(T,C)$ are transposition-invariant.
\end{proof}

\begin{theorem}[Uniform coset marginal]\label{thm:unif}
Let $\varphi:G\twoheadrightarrow A$ be a surjective homomorphism of finite groups and $T:G\to\iota$ arbitrary. In the group table, $p_C(a)=1/|A|$ for every $a$, so $H(C)=\log_2|A|$.
\end{theorem}
\begin{proof}
Each fibre $\varphi^{-1}(a)$ is a coset of $\ker\varphi$, so has $|\ker\varphi|=|G|/|A|$ elements; summing the table over types recovers the fibre count, so $p_C(a)=1/|A|$. A uniform law on $|A|$ points has entropy $\log_2|A|$.
\end{proof}

\begin{theorem}[Abelianization Law, closed form]\label{thm:closed}
Let $\varphi:G\twoheadrightarrow A$ be surjective and let $T:G\to\iota$ satisfy $T(g)=T(g')\Rightarrow\varphi(g)=\varphi(g')$. Then $I(T;\varphi)=\log_2|A|$.
\end{theorem}
\begin{proof}
A positive cell is witnessed by an element of $G$, so determination of the table follows from the hypothesis on $T$; now apply Theorems~\ref{thm:ablaw} and~\ref{thm:unif}.
\end{proof}

\begin{corollary}[Arithmetic form]
If the cycle type of an element of $G$ determines its image in $A=G^{\ab}$, then the factorization type of $f\bmod p$ carries exactly $\log_2|A|$ bits about the abelianization coset of $p$, and the residual type entropy is exactly $H(T)-\log_2|A|$.
\end{corollary}

\section{The converse: a sharp saturation criterion}

\begin{lemma}[Strict pointwise domination]\label{lem:strict}
If $0<x<S$ then $x(-\log S)<\eta(x)$.
\end{lemma}

\begin{lemma}[Row bound]\label{lem:row}
$\eta(p_T(t))\le\sum_c\eta(p(t,c))$ for every $t$.
\end{lemma}
\begin{proof}
Write $\eta(p_T(t))=\sum_c p(t,c)(-\log p_T(t))$ and apply Lemma~\ref{lem:dom} cellwise.
\end{proof}

\begin{lemma}[Strict row bound]\label{lem:strictrow}
If $c_1\ne c_2$ with $p(t,c_1)>0$ and $p(t,c_2)>0$ then $\eta(p_T(t))<\sum_c\eta(p(t,c))$.
\end{lemma}
\begin{proof}
$p(t,c_1)+p(t,c_2)\le p_T(t)$ and $p(t,c_2)>0$ force $p(t,c_1)<p_T(t)$, so the term at $c_1$ obeys Lemma~\ref{lem:strict} strictly while all others obey Lemma~\ref{lem:dom}.
\end{proof}

\begin{theorem}[Saturation Criterion]\label{thm:conv}
For any finite type/coset table, $I(T;C)=H(C)$ if and only if the type determines the coset.
\end{theorem}
\begin{proof}
($\Leftarrow$) is Theorem~\ref{thm:ablaw}. ($\Rightarrow$) Saturation forces $H(T,C)=H(T)$, i.e.\ $\sum_{t,c}\eta(p(t,c))=\sum_t\eta(p_T(t))$. If some row had two positive cells, Lemma~\ref{lem:strictrow} would make that row strictly larger while Lemma~\ref{lem:row} makes every other row at least as large, contradicting equality.
\end{proof}

\begin{corollary}[Ambiguity is strictly costly]\label{cor:amb}
If some type occurs with two distinct cosets then $I(T;C)<H(C)$.
\end{corollary}

\section{The residue dial}

In practice one observes not the coset but the residue $p\bmod m^\ast$. The Artin map $(\mathbb{Z}/m^\ast)^\times\twoheadrightarrow A$ is $m$-to-one with $m=\phi(m^\ast)/|A|$, and conditionally on the coset the residue is independent of the type.

\begin{definition}[Uniform refinement]
Let $\pi:\rho\to\kappa$ be a surjection all of whose fibres have size $m\ge1$. The refinement $J\!\downarrow_\pi$ has cells $p'(t,r)=p(t,\pi(r))/m$.
\end{definition}

\begin{theorem}[Residue-dial invariance]\label{thm:dial}
$H'(T)=H(T)$, $H'(C)=H(C)+\log_2 m$, $H'(T,C)=H(T,C)+\log_2 m$, and therefore $I'(T;C)=I(T;C)$.
\end{theorem}
\begin{proof}
Use $\eta(x/m)=\eta(x)/m+(x/m)\log m$ and the fibrewise rule $\sum_r F(\pi(r))=m\sum_c F(c)$. The type marginal is unchanged since $\sum_r p(t,\pi(r))/m=\sum_c p(t,c)$. For the coset entropy, $p'_C(r)=p_C(\pi(r))/m$ gives
$\sum_r\eta(p'_C(r))=\sum_c\eta(p_C(c))+\log m$ using $\sum_c p_C(c)=1$; the joint entropy computation is identical row by row, using $\sum_c p(t,c)=p_T(t)$ and $\sum_t p_T(t)=1$. Substituting into $I=H(T)+H(C)-H(T,C)$ cancels the two $\log_2 m$ terms.
\end{proof}

\begin{corollary}[The $D_5$ dial at $m^\ast=20$]\label{cor:dial}
For a $D_5$-quintic with quadratic resolvent $\mathbb{Q}(\sqrt{-5})$ the character sends the eight units modulo $20$ four-to-one onto $C_2$ (split $1,3,7,9$; inert $11,13,17,19$), so
\[
I(p\bmod 20;T)=I(T;C)=1 \text{ bit exactly},\qquad H(p\bmod 20)=1+\log_2 4=3 \text{ bits},
\]
while $H(T)=\tfrac15+\tfrac12\log_2 5$ is untouched.
\end{corollary}

\section{Semiprimes, arity, and the which-factor wall}

Model a $k$-almost-prime by $k$ independent uniform elements $x\in G^k$, with observables $T^{(k)}(x)=(T(x_1),\dots,T(x_k))$ and $C^{(k)}(x)=\prod_i\varphi(x_i)\in A$. Since $A$ is abelian, $C^{(k)}$ is a homomorphism.

\begin{theorem}[Multi-prime law]\label{thm:multi}
Let $k\ge1$, $\varphi:G\twoheadrightarrow A$ surjective with $A$ abelian, and suppose $T$ refines $\varphi$. Then $I\bigl(T^{(k)};C^{(k)}\bigr)=\log_2|A|$; in particular the value does not depend on $k$.
\end{theorem}
\begin{proof}
Equality of type vectors forces $\varphi(x_i)=\varphi(x_i')$ for all $i$ and hence equality of the products, so the type vector determines the product coset; $C^{(k)}$ is surjective (put a preimage in one coordinate, identities elsewhere). Apply Theorem~\ref{thm:closed} to $G^k$.
\end{proof}

\begin{theorem}[Which-factor wall]\label{thm:wall}
For $k\ge2$ the observables $\varphi(x_1)$ and $\prod_i\varphi(x_i)$ on $G^k$ are statistically independent, so their mutual information is exactly $0$.
\end{theorem}
\begin{proof}
The map $x\mapsto(\varphi(x_1),\prod_i\varphi(x_i))$ is a homomorphism $G^k\to A\times A$, surjective: given $(a,b)$ take $x=(g_1,g_2,1,\dots,1)$ with $\varphi(g_1)=a$, $\varphi(g_2)=a^{-1}b$. All fibres of a surjective homomorphism have equal size, so the joint law is uniform on $A\times A$, the product of its uniform marginals; independent observables have zero mutual information.
\end{proof}

\section{The transitive quintic row in closed form}

There are five transitive subgroups of $S_5$ up to conjugacy: $C_5$, $D_5$, $F_{20}=C_5\rtimes C_4$, $A_5$, $S_5$. Every cell probability is a $\{2,3,5\}$-smooth rational $2^x3^y5^z$, so $\eta(p)=-p(x\log2+y\log3+z\log5)$ and every entropy is an explicit $\mathbb{Q}$-linear combination of $1$, $L:=\log_2 5$ and $M:=\log_2 3$.

\paragraph{$C_5$ (e.g.\ the real subfield of $\mathbb{Q}(\zeta_{11})$).}
Types $[1^5]$ at rate $1/5$ and $[5]$ at rate $4/5$; the group is abelian so the coset is the Frobenius element itself, five cosets at rate $1/5$. Then $H(T)=L-\tfrac85$, $H(C)=L$, and by Theorem~\ref{thm:dual}, $I(T;C)=H(T)=L-\tfrac85=0.7219\ldots$ with gap $0$.

\paragraph{$D_5$ (e.g.\ $x^5+20x+32$).}
Types $[1^5]$ at $1/10$, $[5]$ at $4/10$, $[1,2,2]$ at $5/10$; abelianization $C_2$ with rotations and reflections as the two cosets, and the type determines the coset. Then
\[
H(T)=\tfrac15+\tfrac L2=1.36096\ldots,\quad H(C)=1,\quad I(T;C)=1,\quad H(T\mid C)=\tfrac L2-\tfrac45=0.36096\ldots
\]
Sharp brackets $1.3607<H(T)<1.36105$ follow from $2.3214<L<2.3221$, in turn from $5^{28}>2^{65}$ and $5^{59}<2^{137}$.

\paragraph{$F_{20}$ (e.g.\ $x^5-2$).}
Types $[1^5]$: $1/20$, $[5]$: $4/20$, $[4]$: $10/20$, $[1,2,2]$: $5/20$; abelianization $C_4$. The ten elements of type $[4]$ split evenly between the two \emph{generators} of $C_4$, so the type $[4]$ straddles two cosets. Then
\[
H(T)=\tfrac{11}{10}+\tfrac L4=1.68048\ldots,\quad H(C)=2,\quad H(T,C)=\tfrac85+\tfrac L4,\quad I(T;C)=\tfrac32 .
\]
By Corollary~\ref{cor:amb} the inequality $I<H(C)$ is forced, and the deficit is exactly the half bit contributed by that one ambiguous type of mass $\tfrac12$ straddling two cosets.

\paragraph{$A_5$ (e.g.\ $x^5+20x+16$).}
Types $[1^5]$: $1/60$, $[1,2,2]$: $15/60$, $[1,1,3]$: $20/60$, $[5]$: $24/60$. $A_5$ is perfect, so $A$ is trivial, $H(C)=0$ and $I(T;C)=0$, while
$H(T)=\tfrac2{15}+\tfrac{7M}{20}+\tfrac{5L}{12}=1.65554\ldots$ All factorization entropy is invisible to congruences: the information-theoretic form of the failure of abelian reciprocity for non-solvable quintics.

\paragraph{$S_5$ (e.g.\ $x^5-x-1$).}
Seven classes with rates $1/120,10/120,15/120,20/120,20/120,30/120,24/120$ for $[1^5]$, $[1,1,1,2]$, $[1,2,2]$, $[1,1,3]$, $[2,3]$, $[1,4]$, $[5]$; abelianization $C_2$ via the sign, determined by the cycle type. Then
$H(T)=\tfrac75+\tfrac{5L}{24}+\tfrac{17M}{40}=2.55734\ldots$, $H(C)=1$, $I(T;C)=1$. The transmitted bit is the Legendre symbol of the discriminant.

