"""Demo B -- the one transmitted bit of the dihedral quintic x^5 + 20x + 32.

Factors f(x) = x^5 + 20x + 32 modulo every prime below a bound, and shows:

  * only the three dihedral shapes [1^5], [5], [1,2,2] occur, at the class rates
    1/10, 4/10, 1/2;
  * the shape is [1,2,2] exactly when -5 is a non-residue mod p, i.e. exactly when
    p = 11, 13, 17, 19 (mod 20) -- agreement 1.0000, prime by prime;
  * the empirical mutual information between the residue p mod 20 and the shape
    converges to its exact value of one bit, while the residue itself carries three
    bits of entropy.
"""

from math import log2
from typing import Dict, Hashable, List, Sequence, Tuple

Poly = List[int]


def _trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def _mul(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    o = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    o[i + j] = (o[i + j] + x * y) % p
    return _trim(o)


def _sub(a: Poly, b: Poly, p: int) -> Poly:
    n = max(len(a), len(b))
    return _trim([((a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0)) % p
                  for i in range(n)])


def _divmod(a: Poly, b: Poly, p: int) -> Tuple[Poly, Poly]:
    a = a[:]
    inv = pow(b[-1], p - 2, p)
    q = [0] * max(0, len(a) - len(b) + 1)
    while a and len(a) >= len(b):
        sh = len(a) - len(b)
        c = (a[-1] * inv) % p
        q[sh] = c
        for i, y in enumerate(b):
            a[i + sh] = (a[i + sh] - c * y) % p
        _trim(a)
    return _trim(q), _trim(a)


def _gcd(a: Poly, b: Poly, p: int) -> Poly:
    a, b = a[:], b[:]
    while b:
        a, b = b, _divmod(a, b, p)[1]
    if a:
        inv = pow(a[-1], p - 2, p)
        a = [(c * inv) % p for c in a]
    return a


def _powmod(base: Poly, e: int, mod: Poly, p: int) -> Poly:
    r, b = [1], _divmod(base, mod, p)[1]
    while e:
        if e & 1:
            r = _divmod(_mul(r, b, p), mod, p)[1]
        b = _divmod(_mul(b, b, p), mod, p)[1]
        e >>= 1
    return r


def frobenius_type(f: Sequence[int], p: int) -> Tuple[int, ...]:
    """Sorted degrees of the irreducible factors of f mod p; () if ramified."""
    fp = _trim([c % p for c in f])
    der = _trim([(i * c) % p for i, c in enumerate(fp)][1:])
    if len(fp) != len(list(f)) or not der or len(_gcd(fp, der, p)) > 1:
        return ()
    degs: List[int] = []
    rem, h = fp, [0, 1]
    for i in range(1, len(fp)):
        if len(rem) - 1 <= 0:
            break
        h = _powmod(h, p, rem, p)
        g = _gcd(rem, _sub(h, [0, 1], p), p)
        d = len(g) - 1
        if d > 0:
            degs.extend([i] * (d // i))
            rem = _divmod(rem, g, p)[0]
            if len(rem) - 1 > 0:
                h = _divmod(h, rem, p)[1]
    if len(rem) - 1 > 0:
        degs.append(len(rem) - 1)
    return tuple(sorted(degs))


def kronecker(a: int, n: int) -> int:
    if n == 0:
        return 1 if a in (1, -1) else 0
    res = 1
    if n < 0:
        n = -n
        if a < 0:
            res = -res
    t = 0
    while n % 2 == 0:
        n //= 2
        t += 1
    if t:
        if a % 2 == 0:
            return 0
        if t % 2 == 1 and a % 8 in (3, 5):
            res = -res
    a %= n
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                res = -res
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            res = -res
        a %= n
    return res if n == 1 else 0


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for q in range(2, int(n ** 0.5) + 1):
        if s[q]:
            s[q * q :: q] = bytearray(len(s[q * q :: q]))
    return [i for i in range(n + 1) if s[i]]


def entropy(counts: Dict[Hashable, int], total: int) -> float:
    return sum(-(c / total) * log2(c / total) for c in counts.values() if c)


def main(limit: int = 50000) -> None:
    f = [32, 20, 0, 0, 0, 1]  # x^5 + 20x + 32
    tc: Dict[Hashable, int] = {}
    rc: Dict[Hashable, int] = {}
    jc: Dict[Hashable, int] = {}
    total = agree = 0
    for p in primes_up_to(limit):
        if p in (2, 5):
            continue
        t = frobenius_type(f, p)
        if not t:
            continue
        total += 1
        tc[t] = tc.get(t, 0) + 1
        r = p % 20
        rc[r] = rc.get(r, 0) + 1
        jc[(t, r)] = jc.get((t, r), 0) + 1
        if (kronecker(-20, p) == -1) == (t == (1, 2, 2)):
            agree += 1

    target = {(1, 1, 1, 1, 1): 0.1, (5,): 0.4, (1, 2, 2): 0.5}
    assert set(tc) <= set(target), "a shape outside the dihedral menu occurred"
    print(f"unramified primes below {limit}: {total}")
    for t in sorted(tc, key=lambda k: -tc[k]):
        print(f"  shape {str(t):>15}: observed {tc[t] / total:.5f}   "
              f"D5 class fraction {target[t]:.5f}")
    print(f"\nagreement of shape with the Kronecker symbol (-20|p): {agree / total:.4f}")
    assert agree == total

    ht, hr, hj = entropy(tc, total), entropy(rc, total), entropy(jc, total)
    print(f"\nH(T)             = {ht:.4f}   exact 1/5 + (log2 5)/2 = {1/5 + log2(5)/2:.4f}")
    print(f"H(p mod 20)      = {hr:.4f}   exact 3")
    print(f"I(p mod 20 ; T)  = {ht + hr - hj:.4f}   exact 1")
    print("\nThe residue dial is a 4-to-1 refinement of the two-element coset alphabet:")
    print("it adds log2(4) = 2 bits of entropy and exactly zero bits of information.")


if __name__ == "__main__":
    main()

