"""Algorithm 1 -- Frobenius type extraction by distinct-degree factorization.

Given a monic integer polynomial f and a prime p not dividing disc(f), returns the
multiset of degrees of the irreducible factors of f mod p, which by Dedekind's theorem
is the cycle type of the Frobenius class of p in the Galois group of f.
"""

from typing import List, Sequence, Tuple

Poly = List[int]  # little-endian coefficients over F_p


def _trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def poly_mul(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    out[i + j] = (out[i + j] + x * y) % p
    return _trim(out)


def poly_sub(a: Poly, b: Poly, p: int) -> Poly:
    n = max(len(a), len(b))
    return _trim([((a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0)) % p
                  for i in range(n)])


def poly_divmod(a: Poly, b: Poly, p: int) -> Tuple[Poly, Poly]:
    a = a[:]
    inv_lead = pow(b[-1], p - 2, p)
    q = [0] * max(0, len(a) - len(b) + 1)
    while a and len(a) >= len(b):
        shift = len(a) - len(b)
        c = (a[-1] * inv_lead) % p
        q[shift] = c
        for i, y in enumerate(b):
            a[i + shift] = (a[i + shift] - c * y) % p
        _trim(a)
    return _trim(q), _trim(a)


def poly_gcd(a: Poly, b: Poly, p: int) -> Poly:
    a, b = a[:], b[:]
    while b:
        a, b = b, poly_divmod(a, b, p)[1]
    if a:
        inv = pow(a[-1], p - 2, p)
        a = [(c * inv) % p for c in a]
    return a


def poly_powmod(base: Poly, exponent: int, modulus: Poly, p: int) -> Poly:
    result, b, e = [1], poly_divmod(base, modulus, p)[1], exponent
    while e:
        if e & 1:
            result = poly_divmod(poly_mul(result, b, p), modulus, p)[1]
        b = poly_divmod(poly_mul(b, b, p), modulus, p)[1]
        e >>= 1
    return result


def frobenius_type(f: Sequence[int], p: int) -> Tuple[int, ...]:
    """Cycle type of Frobenius at p, as a sorted tuple of factor degrees.

    Returns the empty tuple when f mod p is not squarefree (p is ramified).
    Complexity: O(n log p) polynomial multiplications of degree < n, i.e.
    O(n^3 log p) operations in F_p for degree n.
    """
    fp = _trim([c % p for c in f])
    if len(fp) != len(list(f)):
        return ()  # leading coefficient vanished mod p
    deriv = _trim([(i * c) % p for i, c in enumerate(fp)][1:])
    if not deriv or len(poly_gcd(fp, deriv, p)) > 1:
        return ()
    degrees: List[int] = []
    remaining, h = fp, [0, 1]  # h = x
    for i in range(1, len(fp)):
        if len(remaining) - 1 <= 0:
            break
        h = poly_powmod(h, p, remaining, p)                 # h = x^(p^i) mod remaining
        g = poly_gcd(remaining, poly_sub(h, [0, 1], p), p)  # factors of degree exactly i
        d = len(g) - 1
        if d > 0:
            degrees.extend([i] * (d // i))
            remaining = poly_divmod(remaining, g, p)[0]
            if len(remaining) - 1 > 0:
                h = poly_divmod(h, remaining, p)[1]
    if len(remaining) - 1 > 0:
        degrees.append(len(remaining) - 1)
    return tuple(sorted(degrees))


if __name__ == "__main__":
    f = [32, 20, 0, 0, 0, 1]  # x^5 + 20x + 32, a D5 quintic
    for p in [7, 11, 13, 29, 41, 1000003]:
        print(f"p = {p:>8}:  type {frobenius_type(f, p)}")

"""Algorithm 3 -- Quadratic-resolvent identification and the residue dial.

Two linked procedures for a dihedral quintic f (square discriminant, Galois group D5):

(a) `identify_resolvent` locates the quadratic field K whose character is the
    abelianization character of f.  It is NOT the discriminant field, since D5 is
    contained in A5 and the discriminant is a square.  Ramification confines K to
    Q(sqrt d) with d squarefree and supported on the primes dividing disc(f); the
    procedure enumerates those finitely many candidates and keeps the ones whose
    Kronecker symbol matches the observed factorization-type parity at every test
    prime.  A unique survivor at agreement 1.0 is the identification.

(b) `refine_by_residue` implements the residue dial: the uniform m-to-one refinement
    of the coset alphabet into residue classes mod m*.  It adds log2(m) bits to the
    coset and joint entropies and leaves the mutual information unchanged.
"""

from math import log2
from typing import Dict, Hashable, List, Sequence, Tuple

Table = Dict[Tuple[Hashable, Hashable], float]


def kronecker(a: int, n: int) -> int:
    """Kronecker symbol (a | n)."""
    if n == 0:
        return 1 if a in (1, -1) else 0
    result = 1
    if n < 0:
        n = -n
        if a < 0:
            result = -result
    twos = 0
    while n % 2 == 0:
        n //= 2
        twos += 1
    if twos:
        if a % 2 == 0:
            return 0
        if twos % 2 == 1 and a % 8 in (3, 5):
            result = -result
    a %= n
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def squarefree_candidates(ramified_primes: Sequence[int]) -> List[int]:
    """All squarefree d != 1, positive and negative, supported on the given primes."""
    out: List[int] = []
    n = len(ramified_primes)
    for mask in range(1, 1 << n):
        d = 1
        for i in range(n):
            if mask >> i & 1:
                d *= ramified_primes[i]
        out.extend([d, -d])
    return sorted(set(out), key=abs)


def identify_resolvent(
    observations: Sequence[Tuple[int, int]],
    ramified_primes: Sequence[int],
) -> List[Tuple[int, float]]:
    """Rank candidate quadratic fields against observed coset data.

    `observations` is a list of (prime, coset) with coset 0 for a rotation type
    (shapes [1^5], [5]) and 1 for a reflection type ([1,2,2]).  Returns the candidates
    sorted by decreasing agreement with the Kronecker symbol.
    """
    scored: List[Tuple[int, float]] = []
    for d in squarefree_candidates(ramified_primes):
        hits = 0
        used = 0
        for p, coset in observations:
            k = kronecker(d, p)
            if k == 0:
                continue
            used += 1
            if (k == -1) == (coset == 1):
                hits += 1
        if used:
            scored.append((d, hits / used))
    scored.sort(key=lambda x: (-x[1], abs(x[0])))
    return scored


def refine_by_residue(table: Table, fibres: Dict[Hashable, Sequence[Hashable]]) -> Table:
    """Spread each coset's mass uniformly over its fibre of residue classes.

    All fibres must have the same size m; the refinement then satisfies
    H'(T) = H(T), H'(C) = H(C) + log2 m, H'(T,C) = H(T,C) + log2 m, I' = I.
    """
    sizes = {len(v) for v in fibres.values()}
    if len(sizes) != 1:
        raise ValueError("the refinement must be uniformly m-to-one")
    m = sizes.pop()
    out: Table = {}
    for (t, c), v in table.items():
        for r in fibres[c]:
            out[(t, r)] = out.get((t, r), 0.0) + v / m
    return out


def _entropies(table: Table) -> Tuple[float, float, float, float]:
    def eta(x: float) -> float:
        return 0.0 if x <= 0 else -x * log2(x)
    pt: Dict[Hashable, float] = {}
    pc: Dict[Hashable, float] = {}
    for (t, c), v in table.items():
        pt[t] = pt.get(t, 0.0) + v
        pc[c] = pc.get(c, 0.0) + v
    ht = sum(eta(v) for v in pt.values())
    hc = sum(eta(v) for v in pc.values())
    hj = sum(eta(v) for v in table.values())
    return ht, hc, hj, ht + hc - hj


if __name__ == "__main__":
    # (a) identification for x^5 + 20x + 32 using the shapes at small primes
    obs = [(7, 0), (11, 1), (13, 1), (17, 1), (19, 1), (23, 0), (29, 0), (31, 1),
           (37, 1), (41, 0), (43, 0), (47, 0), (53, 1), (59, 1), (61, 0), (67, 0),
           (71, 1), (73, 1), (79, 1), (83, 0)]
    ranked = identify_resolvent(obs, [2, 5])
    print("candidate quadratic resolvents, ranked by agreement:")
    for d, score in ranked[:6]:
        print(f"  Q(sqrt {d:>4}) : agreement {score:.4f}")

    # (b) the residue dial at m* = 20
    D5: Table = {("[1^5]", "rot"): 0.1, ("[5]", "rot"): 0.4, ("[1,2,2]", "refl"): 0.5}
    dial = refine_by_residue(D5, {"rot": [1, 3, 7, 9], "refl": [11, 13, 17, 19]})
    before, after = _entropies(D5), _entropies(dial)
    names = ("H(T)", "H(C)", "H(T,C)", "I(T;C)")
    print("\nresidue dial at m* = 20 (a 4-to-1 refinement):")
    for name, b, a in zip(names, before, after):
        print(f"  {name:>7}: {b:.6f} -> {a:.6f}   (change {a - b:+.6f})")

