"""Visualization: Chebotarev convergence for the dihedral quintic x^5 + 20x + 32.

Left panel: the running frequencies of the three factorization shapes converge to the
dihedral class fractions 1/10, 4/10, 1/2.  Right panel: the running mutual information
between the residue p mod 20 and the factorization shape converges to its exact value
of one bit -- the residue dial adds two bits of entropy (log2 4) and no information.
"""

from math import log2
from typing import Dict, List, Sequence, Tuple

import matplotlib.pyplot as plt

Poly = List[int]


def trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def pmul(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    o = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    o[i + j] = (o[i + j] + x * y) % p
    return trim(o)


def psub(a: Poly, b: Poly, p: int) -> Poly:
    n = max(len(a), len(b))
    return trim([((a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0)) % p for i in range(n)])


def pdivmod(a: Poly, b: Poly, p: int) -> Tuple[Poly, Poly]:
    a = a[:]
    inv = pow(b[-1], p - 2, p)
    q = [0] * max(0, len(a) - len(b) + 1)
    while a and len(a) >= len(b):
        sh = len(a) - len(b)
        c = (a[-1] * inv) % p
        q[sh] = c
        for i, y in enumerate(b):
            a[i + sh] = (a[i + sh] - c * y) % p
        trim(a)
    return trim(q), trim(a)


def pgcd(a: Poly, b: Poly, p: int) -> Poly:
    a, b = a[:], b[:]
    while b:
        a, b = b, pdivmod(a, b, p)[1]
    if a:
        inv = pow(a[-1], p - 2, p)
        a = [(c * inv) % p for c in a]
    return a


def ppowmod(base: Poly, e: int, mod: Poly, p: int) -> Poly:
    r, b = [1], pdivmod(base, mod, p)[1]
    while e:
        if e & 1:
            r = pdivmod(pmul(r, b, p), mod, p)[1]
        b = pdivmod(pmul(b, b, p), mod, p)[1]
        e >>= 1
    return r


def factorization_type(f: Sequence[int], p: int) -> Tuple[int, ...]:
    fp = trim([c % p for c in f])
    der = trim([(i * c) % p for i, c in enumerate(fp)][1:])
    if len(fp) != 6 or not der or len(pgcd(fp, der, p)) > 1:
        return ()
    degs: List[int] = []
    F, h = fp, [0, 1]
    for i in range(1, 6):
        if len(F) - 1 <= 0:
            break
        h = ppowmod(h, p, F, p)
        g = pgcd(F, psub(h, [0, 1], p), p)
        d = len(g) - 1
        if d > 0:
            degs.extend([i] * (d // i))
            F = pdivmod(F, g, p)[0]
            if len(F) - 1 > 0:
                h = pdivmod(h, F, p)[1]
    if len(F) - 1 > 0:
        degs.append(len(F) - 1)
    return tuple(sorted(degs))


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for q in range(2, int(n**0.5) + 1):
        if s[q]:
            s[q * q :: q] = bytearray(len(s[q * q :: q]))
    return [i for i in range(n + 1) if s[i]]


def entropy(counts: Dict[object, int], total: int) -> float:
    return sum(-(c / total) * log2(c / total) for c in counts.values() if c)


def main(limit: int = 120000) -> None:
    f = [32, 20, 0, 0, 0, 1]
    tc: Dict[object, int] = {}
    rc: Dict[object, int] = {}
    jc: Dict[object, int] = {}
    xs: List[int] = []
    rates: Dict[Tuple[int, ...], List[float]] = {(1, 1, 1, 1, 1): [], (5,): [], (1, 2, 2): []}
    info: List[float] = []
    total = 0
    for p in primes_up_to(limit):
        if p in (2, 5):
            continue
        t = factorization_type(f, p)
        if not t:
            continue
        total += 1
        tc[t] = tc.get(t, 0) + 1
        r = p % 20
        rc[r] = rc.get(r, 0) + 1
        jc[(t, r)] = jc.get((t, r), 0) + 1
        if total % 20 == 0:
            xs.append(total)
            for key in rates:
                rates[key].append(tc.get(key, 0) / total)
            info.append(entropy(tc, total) + entropy(rc, total) - entropy(jc, total))

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12.5, 4.8))

    colors = {(1, 1, 1, 1, 1): "#2a9d8f", (5,): "#264653", (1, 2, 2): "#e76f51"}
    names = {(1, 1, 1, 1, 1): r"$[1^5]$ (splits completely)", (5,): r"$[5]$ (inert)",
             (1, 2, 2): r"$[1,2,2]$ (reflection)"}
    targets = {(1, 1, 1, 1, 1): 0.1, (5,): 0.4, (1, 2, 2): 0.5}
    for key, series in rates.items():
        ax1.plot(xs, series, color=colors[key], lw=1.5, label=names[key])
        ax1.axhline(targets[key], color=colors[key], ls=":", lw=1.2)
    ax1.set_xlabel("unramified primes processed")
    ax1.set_ylabel("observed frequency")
    ax1.set_title(r"Chebotarev histogram of $x^5+20x+32$" "\n"
                  r"converging to the $D_5$ class fractions $\{1/10,\,4/10,\,1/2\}$")
    ax1.legend(frameon=False, fontsize=9)
    ax1.set_ylim(0, 0.62)
    ax1.spines[["top", "right"]].set_visible(False)

    ax2.plot(xs, info, color="#4361ee", lw=1.6)
    ax2.axhline(1.0, color="#e76f51", ls="--", lw=1.4, label="exact value: 1 bit")
    ax2.set_xlabel("unramified primes processed")
    ax2.set_ylabel("bits")
    ax2.set_ylim(0.5, 1.5)
    ax2.set_title(r"$I(p \bmod 20\,;\,T)$ converging to exactly one bit" "\n"
                  r"(the residue carries $3$ bits of entropy, $1$ of information)")
    ax2.legend(frameon=False, fontsize=9)
    ax2.spines[["top", "right"]].set_visible(False)

    fig.tight_layout()
    fig.savefig("chebotarev_convergence.png", dpi=170)
    print("wrote chebotarev_convergence.png")


if __name__ == "__main__":
    main()
